import XCTest
import Security
@testable import LabsMobileCore
final class CollectorTrustTests: XCTestCase {
    private func trust(damage: Bool = false, year: Int = 2026) throws -> SecTrust {
        var der = Data(base64Encoded:"")!
        if damage { der[der.count-1] ^= 1 }
        let certs = [SecCertificateCreateWithData(nil,der as CFData)!,SecCertificateCreateWithData(nil,Data(base64Encoded:"")! as CFData)!]
        var trust: SecTrust?
        XCTAssertEqual(SecTrustCreateWithCertificates(certs as CFArray,SecPolicyCreateSSL(true,CollectorTrust.host as CFString),&trust),errSecSuccess)
        let date = ISO8601DateFormatter().date(from:"\(year)-10-17T22:00:00Z")!
        SecTrustSetVerifyDate(trust!,date as CFDate); SecTrustSetNetworkFetchAllowed(trust!,false)
        return trust!
    }
    func testPublishedMicrosoftRootValidatesActualCollectorChain() throws { XCTAssertTrue(CollectorTrust.validate(try trust(),host:CollectorTrust.host)) }
    func testAnchorCannotAuthorizeOtherHosts() throws { XCTAssertFalse(CollectorTrust.validate(try trust(),host:"example.invalid")) }
    func testExpiredCertificatesAreRejected() throws { XCTAssertFalse(CollectorTrust.validate(try trust(year:2030),host:CollectorTrust.host)) }
    func testDamagedSignatureIsRejected() throws { XCTAssertFalse(CollectorTrust.validate(try trust(damage:true),host:CollectorTrust.host)) }
}
